import{_ as t,o as l,c as S,j as e,a as s}from"./chunks/framework.DJo0M80U.js";const R=JSON.parse('{"title":"使用过 Vue SSR 吗？说说 SSR？","description":"Vue.js 是构建客户端应用程序的框架。默认情况下，可以在浏览器中输出 Vue 组件，进行生成 DOM 和操作 DOM。然而，也可以将同一个组件渲染为服务端的 HTML 字符串，将它们直接发送到浏览器，最后将这些静态标记\\"激活\\"为客户端上完全可交互的应用程序。 即：SSR大致的。","frontmatter":{"title":"使用过 Vue SSR 吗？说说 SSR？","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","面试复习"],"description":"Vue.js 是构建客户端应用程序的框架。默认情况下，可以在浏览器中输出 Vue 组件，进行生成 DOM 和操作 DOM。然而，也可以将同一个组件渲染为服务端的 HTML 字符串，将它们直接发送到浏览器，最后将这些静态标记\\"激活\\"为客户端上完全可交互的应用程序。 即：SSR大致的。","sidebarWeight":26,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/面试/使用过 Vue SSR 吗？说说 SSR？.md"},"headers":[],"relativePath":"posts/Vue系统教程/08-面试复习/使用过 Vue SSR 吗？说说 SSR？.md","filePath":"posts/Vue系统教程/08-面试复习/使用过 Vue SSR 吗？说说 SSR？.md"}'),n={name:"posts/Vue系统教程/08-面试复习/使用过 Vue SSR 吗？说说 SSR？.md"};function u(r,a,o,i,p,d){return l(),S("div",null,[...a[0]||(a[0]=[e("div",null,[e("h1",{id:"使用过-vue-ssr-吗-说说-ssr",tabindex:"-1"},[s("使用过 Vue SSR 吗？说说 SSR？ "),e("a",{class:"header-anchor",href:"#使用过-vue-ssr-吗-说说-ssr","aria-label":'Permalink to "使用过 Vue SSR 吗？说说 SSR？"'},"​")]),e("blockquote",null,[e("p",null,'本节目标：理解“使用过 Vue SSR 吗？说说 SSR？”的核心思路，并能把它用于实际开发或面试表达。 Vue.js 是构建客户端应用程序的框架。默认情况下，可以在浏览器中输出 Vue 组件，进行生成 DOM 和操作 DOM。然而，也可以将同一个组件渲染为服务端的 HTML 字符串，将它们直接发送到浏览器，最后将这些静态标记"激活"为客户端上完全可交互的应用程序。')]),e("p",null,"即：SSR大致的意思就是vue在客户端将标签渲染成的整个 html 片段的工作在服务端完成，服务端形成的html 片段直接返回给客户端这个过程就叫做服务端渲染。"),e("div",{class:"language- vp-adaptive-theme"},[e("button",{title:"Copy Code",class:"copy"}),e("span",{class:"lang"}),e("pre",{class:"shiki shiki-themes github-light github-dark vp-code",tabindex:"0","v-pre":""},[e("code",null,[e("span",{class:"line"},[e("span",null,"**服务端渲染的优点：**")])])])]),e("p",null,"更好的 SEO： 因为 SPA 页面的内容是通过 Ajax 获取，而搜索引擎爬取工具并不会等待 Ajax 异步完成后再抓取页面内容，所以在 SPA 中是抓取不到页面通过 Ajax 获取到的内容；而 SSR 是直接由服务端返回已经渲染好的页面（数据已经包含在页面中），所以搜索引擎爬取工具可以抓取渲染好的页面；"),e("p",null,"更快的内容到达时间（首屏加载更快）： SPA 会等待所有 Vue 编译后的 js 文件都下载完成后，才开始进行页面的渲染，文件下载等需要一定的时间等，所以首屏渲染需要一定的时间；SSR 直接由服务端渲染好页面直接返回显示，无需等待下载 js 文件及再去渲染等，所以 SSR 有更快的内容到达时间；"),e("div",{class:"language- vp-adaptive-theme"},[e("button",{title:"Copy Code",class:"copy"}),e("span",{class:"lang"}),e("pre",{class:"shiki shiki-themes github-light github-dark vp-code",tabindex:"0","v-pre":""},[e("code",null,[e("span",{class:"line"},[e("span",null,"**服务端渲染的缺点：**")])])])]),e("p",null,"更多的开发条件限制： 例如服务端渲染只支持 beforCreate 和 created 两个钩子函数，这会导致一些外部扩展库需要特殊处理，才能在服务端渲染应用程序中运行；并且与可以部署在任何静态文件服务器上的完全静态单页面应用程序 SPA 不同，服务端渲染应用程序，需要处于 Node.js server 运行环境；"),e("p",null,"更多的服务器负载：在 Node.js 中渲染完整的应用程序，显然会比仅仅提供静态文件的 server 更加大量占用CPU 资源 (CPU-intensive - CPU 密集)，因此如果你预料在高流量环境 ( high traffic ) 下使用，请准备相应的服务器负载，并明智地采用缓存策略。"),e("p",null,[s("如果没有 SSR 开发经验的同学，可以参考本文作者的另一篇 SSR 的实践文章"),e("a",{href:"https://juejin.im/post/6844903824956588040",target:"_blank",rel:"noreferrer"},"《"),s("Vue SSR 踩坑之旅》，里面 SSR 项目搭建以及附有项目源码。")])],-1)])])}const h=t(n,[["render",u]]);export{R as __pageData,h as default};
